433	  /* The platform's OWN actions, one per product — called, never reimplemented.
434	     Each owns impersonation refusal, the email-verification gate, the per-user
435	     cap, a server-side re-quote before charging, and the wallet/card split.
436	     A game order must go through `payAndDeployGame`: it validates the family's
437	     variant, claims the play subdomain and sizes the VM from the tier's base
438	     plan, none of which `payAndDeploy` knows anything about. */
439	  /* One action per product. `submitHosting` / `submitEmail` are thin adapters
440	     (lib/nx/submit-hosting.ts) around functions that take positional arguments
441	     instead of FormData — they translate, they do not decide. */
442	  const action = isGame ? payAndDeployGame
443	               : isHosting ? submitHosting
444	               : isEmail ? submitEmail
445	               : isDomains ? purchaseDomain
446	               : payAndDeploy;
447	  const [state, submit, submitting] = useActionState(
448	    action as typeof payAndDeploy,
449	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } }
450	  );
451	  /* The card fields are up FROM THE MOMENT this step opens, not after the
452	   * button is pressed. Stripe will not render a Payment Element without a
453	   * session, so one is prepared here as soon as an amount is known.
454	   *
455	   * THE GUARD THAT MAKES THIS SAFE, and it is the whole design:
456	   * this only ever runs while `cardDue > 0`. With a card leg due, the order
457	   * action creates the session and returns it WITHOUT placing the order or
458	   * touching the wallet — fulfilment places it after the card clears
459	   * ("the wallet is never touched before the card clears", lib/actions.ts).
460	   * If the balance covered the total there would be no card leg, and calling
461	   * the same action would PLACE THE ORDER outright — so an order would be
462	   * committed by merely arriving at a step. Never call this unguarded.
463	   *
464	   * The session is also rebuilt whenever the AMOUNT changes, keyed on
465	   * `preparedFor`. A session holds the figure it was created with; letting a
466	   * promo code or the balance toggle move the total underneath it would charge
467	   * a number the customer never agreed to. */
468	  const [prepared, setPrepared] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
469	  const [preparedFor, setPreparedFor] = useState<number | null>(null);
470	  const [prepError, setPrepError] = useState<string | null>(null);
471	  /* The card panel's confirm, hoisted so ONE button drives everything. In a ref,
472	     not state: it changes identity whenever Stripe re-renders, and storing it in
473	     state would re-render this component every time it did. */
474	  const cardConfirm = useRef<(() => Promise<void>) | null>(null);
475	  /* The ref alone is not enough. The pay button's `disabled` reads this, and a
476	     ref write does NOT re-render — so the button computed "not ready" once,
477	     while Stripe was still initialising, and never recomputed when the confirm
478	     arrived. It stayed grey with a perfectly valid card typed in. The FUNCTION
479	     stays in the ref (it changes identity on every Stripe re-render, and holding
480	     it in state would re-render the wizard each time); this boolean is the part
481	     the UI actually needs to react to. */
482	  const [canConfirm, setCanConfirm] = useState(false);
483	  const [paying, setPaying] = useState(false);
484	  const [payError, setPayError] = useState<string | null>(null);
485	  const preparing = useRef(false);
486	
487	  useEffect(() => {
488	    /* Only while this step is ON SCREEN. The deck renders every slide, so
489	       without this the session was being opened at Stripe the moment a customer
490	       picked a plan — one abandoned session each for everyone who never reaches
491	       checkout. */
492	    /* Every product EXCEPT domains, which have no card session of their own.
493	       Safe because each action, with a card leg due, creates the session and
494	       stops — it does not place the order. That was NOT true while hosting went
495	       through `orderHostingAccount`, which ignores the wallet toggle and so
496	       always committed; it now goes through `placeHostingOrder`, which honours
497	       it and returns a session instead. If you point this at a new product,
498	       verify its action cannot commit when money is owed BEFORE adding it. */
499	    /* Domains included. `purchaseDomain` branches exactly like hosting's:
500	       with `cardCents > 0` it stashes an intent, creates the session and
501	       returns it; only "Wallet covers it — register immediately" registers. So
502	       preparing is safe under the `cardDue > 0` guard below, and ONLY under it —
503	       a domain registration is non-refundable, and calling this with the balance
504	       covering the total would buy the name outright. */
505	    const CAN_PREPARE = true;
506	    /* `ready` too: do not ask the server to price an INCOMPLETE order. Email
507	       requires a domain, and without one `orderEmailHosting` refuses with
508	       "Enter a domain." — which this panel then showed as a failure, on a step
509	       the customer had not finished filling in. Nothing is asked for until the
510	       order is complete enough to actually be placed. */
511	    if (!active || !methods.card || !CAN_PREPARE || !ready) return;
512	    const form = formRef.current;
513	    if (!form || price === null || pricing) return;
514	    if (cardDue <= 0) { setPrepared(null); setPreparedFor(null); return; }
515	    if (preparedFor === cardDue || preparing.current) return;
516	
517	    preparing.current = true;
518	    const t = setTimeout(async () => {
519	      try {
520	        const fd = new FormData(form);
521	        const res = await (action as typeof payAndDeploy)({}, fd);
522	        if (res && "checkout" in res && res.checkout) {
523	          setPrepared(res.checkout);
524	          setPreparedFor(cardDue);
525	          setPrepError(null);
526	        } else if (res && "error" in res && res.error) {
527	          /* A real refusal — an unavailable plan, a taken domain, no capacity.
528	             Shown here rather than swallowed, because otherwise the panel just
529	             sits empty with no explanation. */
530	          setPrepared(null);
531	          setPrepError(res.error);
532	        }
533	      } catch (e) {
534	        /* The real reason, not a generic apology — these are our own action's
535	           messages, never a raw internal error. */
536	        setPrepError(e instanceof Error && e.message
537	          ? e.message
538	          : "The secure card form could not be prepared. Press Complete deployment to retry.");
539	      } finally {
540	        preparing.current = false;
541	      }
542	    }, 400);
543	    return () => { clearTimeout(t); preparing.current = false; };
544	  }, [active, methods.card, price, pricing, cardDue, preparedFor, action, o.service, ready]);
