567	   * would let a customer choose PayPal in production and be charged by card.
568	   *
569	   * So a rail is offered only where BOTH are true: the platform can take money
570	   * through it, and this wizard implements it. Delete an entry from here the
571	   * moment its rail is actually wired, not before. */
572	  const IMPLEMENTED_HERE: Record<string, boolean> = { card: true, paypal: true, crypto: false };
573	  /* Domains have no PayPal rail anywhere on the platform (there is no
574	     `createDomainPayPalOrder`), so the tile is off for that product rather than
