589	  const [idemKey] = useState(() =>
590	    (globalThis.crypto?.randomUUID?.() ?? `nx-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`));
591	  const [ppError, setPpError] = useState<string | null>(null);
592	  const [ppPendingId, setPpPendingId] = useState<string | null>(null);
593	  const covered = price !== null && cardDue <= 0;
594	  const region = cat.regions.find((r) => r.key === o.region);
595	  const os = cat.oses.find((x) => x.id === o.osId);
596	  /* Which of these the PRODUCT actually has. A VPS and a game server live in a
597	     region and run an image; shared hosting, mailboxes and a domain
598	     registration do neither. */
599	  const hasRegion = o.service === "vps" || o.service === "game";
600	  const hasOs = o.service === "vps";
601	
602	  return (
603	    <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_400px]">
604	      {/* ── left: how to pay ── */}
