606	        <div className="grid gap-2 sm:grid-cols-3">
607	          {PAY.map(([k, label, on]) => (
608	            <button key={k} onClick={() => on && setPay(k)} disabled={!on}
609	                    className={"card card-i flex items-center gap-2.5 p-3 text-left " +
610	                               (pay === k && on ? "card-on " : "") +
611	                               (on ? "" : "cursor-not-allowed opacity-45")}>
612	              <Plate name={k === "card" ? "card" : k === "paypal" ? "handshake" : "bolt"} size={22} />
613	              <span className="flex min-w-0 flex-col">
614	                <span className="trunc text-[13px] font-bold text-white">{label}</span>
615	                {/* Honest about a method the platform cannot take money through,
616	                    rather than a tile that fails after it is picked. */}
617	                {!on && <span className="trunc text-[10.5px] text-tx-faint">Not enabled</span>}
618	              </span>
619	            </button>
620	          ))}
621	        </div>
622	
623	        <div className="card relative flex min-h-[280px] items-center justify-center p-4">
624	          {covered ? (
625	            <div className="flex max-w-[360px] flex-col items-center gap-1.5 text-center">
