641	          ) : pay === "paypal" && paypalUsable ? (
642	            <div className="flex w-full max-w-[380px] flex-col items-center gap-3">
643	              <span className="text-center text-[11.8px] leading-[1.5] text-tx-faint">
644	                {/* Said before they commit: PayPal covers what is LEFT after the
645	                    balance, because the server does the wallet split first. */}
646	                PayPal covers the {money(cardDue > 0 ? cardDue : 0)} left after your balance.
647	              </span>
648	              {ppError && (
649	                <span className="w-full rounded-[8px] border border-[rgba(239,66,108,0.3)] bg-[rgba(60,10,26,0.5)]
650	                                 px-3 py-2 text-center text-[11.5px] text-rose">{ppError}</span>
651	              )}
652	              <PayPalScriptProvider options={{ clientId: paypalClientId!, currency: "USD", intent: "capture" }}>
653	                <div className="w-full">
654	                  <PayPalButtons
655	                    fundingSource={FUNDING.PAYPAL}
656	                    style={{ layout: "horizontal", color: "gold", shape: "pill", height: 45, tagline: false }}
657	                    createOrder={async () => {
658	                      setPpError(null);
659	                      const form = formRef.current;
660	                      if (!form) throw new Error("form not ready");
661	                      /* The SAME FormData the card path submits — read off the
662	                         real form, never rebuilt by hand. */
663	                      const fd = new FormData(form);
664	                      /* The tile is unreachable without a service chosen, but the
665	                         dispatcher is a money path — assert rather than cast. */
666	                      if (!o.service) { setPpError("Pick a service first."); throw new Error("no service"); }
667	                      const res = await openWizardPayPalOrder(o.service, fd);
668	                      if ("error" in res) { setPpError(res.error); throw new Error(res.error); }
669	                      setPpPendingId(res.pendingId);
670	                      return res.paypalOrderId;
671	                    }}
672	                    onApprove={async (data) => {
673	                      if (!ppPendingId) { setPpError("That payment could not be matched. Please try again."); return; }
674	                      const res = await captureExternalPayPalOrder(data.orderID, ppPendingId);
675	                      if (res.error) { setPpError(res.error); return; }
676	                      /* The action decides where a completed order lands — the
677	                         wizard does not guess a URL. */
678	                      if (res.redirect) window.location.assign(res.redirect);
679	                    }}
680	                    onError={() => setPpError("PayPal couldn't complete this payment. Please try again.")}
681	                  />
682	                </div>
683	              </PayPalScriptProvider>
684	            </div>
685	          ) : checkout ? (
686	            /* The card fields, in the panel — never an overlay. They can only
687	               appear once the ORDER ACTION has produced a session, because the
688	               session is what fixes the amount. Creating one earlier, on arrival
689	               at this step, would let the promo code or the balance toggle move
690	               the total afterwards and leave a stale session charging a figure
691	               the customer never agreed to. */
692	            <div className="w-full self-start">
693	              <NxCardFields
694	                clientSecret={checkout.clientSecret}
695	                publishableKey={checkout.publishableKey}
696	                onConfirmReady={(fn) => { cardConfirm.current = fn; setCanConfirm(!!fn); }}
697	                onBusy={(b, err) => { setPaying(b); setPayError(err); }}
698	              />
699	            </div>
700	          ) : prepError ? (
701	            /* The refusal, SHOWN. It was being captured into state and never
702	               rendered, so a hosting order that the server had turned down —
703	               no capacity, a taken domain, an unverified email — left this panel
704	               sitting blank with no reason given, and nothing to act on. */
705	            <div className="flex max-w-[420px] flex-col items-center gap-2 text-center">
706	              <Icon name="warntriangle" size={24} className="text-amber" />
707	              <span className="text-[14px] font-bold text-white">This order can&apos;t be taken yet</span>
708	              <span className="text-[11.8px] leading-[1.5] text-tx-mute">{prepError}</span>
709	              <button type="button" onClick={onEdit}
710	                      className="btn-ghost mt-1 h-[34px] px-4 text-[12.5px]">Change the order</button>
711	            </div>
712	          ) : (
713	            <div className="flex max-w-[380px] flex-col items-center gap-1.5 text-center">
714	              <Icon name="lock" size={24} className="opacity-70" />
715	              <span className="text-[14px] font-bold text-white">
716	                {pricing || preparing.current ? "Preparing your secure card form…"
717	                  : !ready ? "Finish the steps above"
718	                  : cardDue <= 0 ? "Covered by your balance"
719	                  : "Card details appear here"}
720	              </span>
721	              {/* Don't promise fields that cannot arrive. They need a complete
722	                  order (so the server can price it) AND an amount actually owed
723	                  on a card — with the balance covering the total there is no
724	                  card leg and never will be. */}
725	              <span className="text-[11.8px] leading-[1.5] text-tx-faint">
726	                {!ready ? "The secure card fields load here once the order is complete."
727	                  : cardDue <= 0 ? "No card needed. Turn the balance off in the summary to pay another way."
728	                  : "The secure fields load right here. Nxeon never sees your card number."}
729	              </span>
730	            </div>
731	          )}
732	        </div>
733	      </div>
734	
735	      {/* ── right: the order, and everything about the money ── */}
736	      <div className="card flex h-fit flex-col gap-3 p-3.5">
737	        <div className="flex items-center justify-between gap-3">
738	          <span className="text-[14px] font-extrabold tracking-[-0.02em] text-white">Order summary</span>
739	          {/* Goes back to Configure rather than opening a second editor — one
740	              place to change the order, not two that can disagree. */}
741	          <button onClick={onEdit} className="text-[12px] font-semibold text-cyan hover:text-white">
742	            Edit
743	          </button>
744	        </div>

