// Ephemeral verification script — deleted after use.
// Walks /dashboard/deploy: Game Servers -> pick a game -> cheapest tier -> payment step.
// Then repeats picking the MOST EXPENSIVE tier to see if card fields ever mount.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const OUT = "/tmp/claude-0/-/a847f019-50a6-4b60-bcba-1133f2a3ca8a/scratchpad/game-pay";
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
page.on("console", (m) => { if (m.type() === "error") console.log("[console error]", m.text()); });

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await Promise.all([
  page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
  page.click("button.btn-primary"),
]);

// Grab wallet balance off the dashboard top bar for reference.
await page.goto(`${BASE}/dashboard`, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
await page.waitForTimeout(1500);
await page.screenshot({ path: `${OUT}/00-dashboard.png`, fullPage: true });

async function runGameFlow(tierChoice) {
  await page.goto(`${BASE}/dashboard/deploy`, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
  await page.waitForTimeout(1500);

  // Pick "Game Servers" service tile.
  const svcTile = page.locator("button, [role=button]").filter({ hasText: /Game Servers/i }).first();
  await svcTile.click({ timeout: 10000 }).catch(async () => {
    console.log("Could not find Game Servers tile directly, dumping page text");
  });
  await page.waitForTimeout(1000);

  // Pick the first game family card.
  const gameCard = page.locator("button, [role=button]").filter({ hasText: /./ }).first();
  // Instead, look within the game grid area - click first game tile with an image.
  const gameTiles = page.locator("button").filter({ has: page.locator("img") });
  const count = await gameTiles.count();
  console.log("game tiles found:", count);
  if (count > 0) {
    await gameTiles.nth(0).click({ timeout: 10000 }).catch(() => {});
  }
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `${OUT}/01-${tierChoice}-after-game-pick.png`, fullPage: true });

  // Now on tier step - find tier "Pick" cards (they usually show price /mo).
  const tierCards = page.locator("button").filter({ hasText: /\/mo/i });
  const tierCount = await tierCards.count();
  console.log("tier cards found:", tierCount);
  let idx = 0;
  if (tierChoice === "expensive" && tierCount > 0) idx = tierCount - 1;
  if (tierCount > 0) {
    await tierCards.nth(idx).click({ timeout: 10000 }).catch(() => {});
  }
  await page.waitForTimeout(800);

  // Fill server name if there's an input.
  const nameInput = page.locator('input[type="text"]').first();
  if (await nameInput.count()) {
    await nameInput.fill(`test-server-${tierChoice}`).catch(() => {});
  }
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${OUT}/02-${tierChoice}-tier-configured.png`, fullPage: true });

  // Click through Continue/Next buttons until we reach Payment step or run out.
  for (let i = 0; i < 6; i++) {
    const nextBtn = page.locator("button").filter({ hasText: /^(Continue|Next|Review|Payment)$/i }).first();
    const paymentTabVisible = await page.locator("text=/Order summary/i").count();
    if (paymentTabVisible > 0) break;
    if (await nextBtn.count()) {
      await nextBtn.click().catch(() => {});
      await page.waitForTimeout(900);
    } else {
      break;
    }
  }
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${OUT}/03-${tierChoice}-payment-step.png`, fullPage: true });

  const coveredText = await page.locator("text=/Covered by your balance/i").count();
  const cardFieldFrame = await page.locator("iframe[name*=privateStripeFrame], iframe[src*=stripe]").count();
  const cardDetailsAppear = await page.locator("text=/Card details appear here/i").count();
  console.log(`[${tierChoice}] covered-by-balance visible:`, coveredText, "| stripe iframe count:", cardFieldFrame, "| 'card details appear here' visible:", cardDetailsAppear);

  return { coveredText, cardFieldFrame, cardDetailsAppear };
}

const cheap = await runGameFlow("cheap");
const expensive = await runGameFlow("expensive");

console.log("RESULT cheap:", JSON.stringify(cheap));
console.log("RESULT expensive:", JSON.stringify(expensive));

await browser.close();

