180	 *
181	 * `gameOrderGate` and `gameIntentFromFormData` now live in lib/game-order.ts (a
182	 * plain module) rather than here — see that file for why: a helper that takes an
183	 * already-authenticated `user` (or does no auth at all) must never be exported
184	 * from a `"use server"` file, since every such export is independently
185	 * network-callable (test/auth-lockouts.test.ts's "HAZARD" suite).
186	 */
187	
188	/**
189	 * Wizard checkout for a game server — the game analogue of `payAndDeploy`, built on
190	 * the SAME audited machinery: it reuses `walletSplit` for the wallet/card split,
191	 * `placeGameOrder` (lib/game-order.ts) as the ONE debit path, and — when a card leg
192	 * is needed — `createGameOrderCheckout` + the shared Stripe fulfilment bus
193	 * (lib/fulfil-checkout.ts) that also settles VPS orders. No new charge path.
194	 *
195	 * MONEY: game bills FULL from month 1 — no first-month-free, no VAT change. An
196	 * optional checkout coupon may still discount the plan portion (gameOrderQuote,
197	 * lib/game-order.ts). The charge is the DB-fed term price net of any coupon
198	 * (`gameOrderQuote.chargeCents`), the SOLD price is stamped on the Checkout
199	 * session BEFORE the card is charged, and fulfilment settles that exact figure
200	 * (never re-quoted after the card cleared).
201	 * displayed (wizard) === charged (here) === renewed (renewalCharge).
202	 */
203	/**
204	 * Preview a checkout coupon against the customer's current game-server
205	 * selection, so the deploy wizard can show the real discounted total before
206	 * they commit. Read-only: it quotes, it does not claim — the claim + all
207	 * once-per-person guards happen in placeGameOrder at deploy time. Mirrors
208	 * lib/actions.ts previewOrderCoupon exactly, for the game order path.
209	 */
210	export async function previewGameOrderCoupon(input: {
211	  gamePlanId: string;
212	  termMonths?: number;
213	  variant?: string;
214	  subdomain?: string;
215	  dedicatedIp?: boolean;
216	  config?: Record<string, unknown> | null;
217	  couponCode: string;
218	}): Promise<{ ok: boolean; label?: string; discountCents?: number; error?: string }> {
219	  await requireUser();
220	  const code = String(input.couponCode ?? "").trim().toUpperCase();
221	  if (!code) return { ok: false, error: "Enter a code." };
222	  try {
223	    const quote = await gameOrderQuote({
224	      gamePlanId: input.gamePlanId,
225	      termMonths: Number(input.termMonths ?? 1),
226	      variant: input.variant,
227	      subdomain: input.subdomain,
228	      dedicatedIp: !!input.dedicatedIp,
229	      config: input.config,
230	      couponCode: code,
231	    });
232	    if (quote.couponError) return { ok: false, error: quote.couponError };
233	    if (quote.couponDiscountCents > 0) return { ok: true, label: quote.couponLabel, discountCents: quote.couponDiscountCents };
234	    return { ok: false, error: "That code doesn’t apply to this order." };
235	  } catch (e) {
236	    if (e instanceof GameOrderError) return { ok: false, error: e.message };
237	    return { ok: false, error: "Couldn’t check that code. Try again." };
238	  }
239	}
240	
241	export async function payAndDeployGame(
242	  _prev: unknown,
243	  formData: FormData,
244	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
245	  const user = await requireUser();
246	  // Spend path: never move a customer's money while an admin is impersonating them.
247	  // Caught so an impersonating admin sees this message inline instead of a page
248	  // crash — the bare throw used to hit the wizard's generic error screen on
249	  // every payment attempt.
250	  try {
251	    await assertNotImpersonating();
252	  } catch (e) {
253	    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
254	  }
255	  // Purchase gate: an unverified address means we cannot reach the person we are
256	  // about to charge (see lib/email-verification.ts). Consulted before any money moves.
257	  const unverified = await emailVerificationError(user);
258	  if (unverified) return { error: unverified };
259	  const gateErr = await gameOrderGate(user);
260	  if (gateErr) return { error: gateErr };
261	
262	  const intent = gameIntentFromFormData(formData);
263	
264	  let quote;
265	  try {
266	    quote = await gameOrderQuote(intent);
267	  } catch (e) {
268	    if (e instanceof GameOrderError) return { error: e.message };
269	    throw e;
270	  }
271	
272	  // The DB-fed term price, net of any valid coupon discount. No VAT for game.
273	  const chargeCents = quote.chargeCents;
274	
275	  // Wallet-aware split — the wizard computes the identical split (lib/wallet-split.ts)
276	  // from the same inputs, so what the customer sees === what we charge. `useWallet`
277	  // defaults ON (only "0" turns it off).
278	  const useWallet = formData.get("useWallet") !== "0";
279	  const { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });
280	
281	  // Card portion is $0 (the wallet covers the whole charge) → provision straight
282	  // away through the audited debit. `placeGameOrder` debits the FULL chargeCents
283	  // from the wallet; its balance check holds because cardCents <= 0 means the
284	  // balance already covers the charge.
285	  if (cardCents <= 0) {
286	    let serverId: string;
287	    try {
288	      serverId = await placeGameOrder(user, intent, null);
289	    } catch (e) {
290	      if (e instanceof GameOrderError) return { error: e.message };
291	      throw e;
292	    }
293	    // Wallet-only is still a real payment — same `?purchase=1` marker the card/
294	    // Stripe path gets via reportPurchase, so ProvisioningOverlay's "just paid"
295	    // success screen shows for this path too.
296	    redirect(`/dashboard/servers/${serverId}?purchase=1`);
297	  }
298	
299	  // Card leg > 0 → charge ONLY the remainder on the card. On payment success the
300	  // confirm/webhook route credits this card amount to the wallet and THEN
301	  // placeGameOrder debits the full chargeCents, so the wallet naturally absorbs the
302	  // applied balance and the card the rest — the wallet is never touched before the
303	  // card clears. The SOLD price is handed over EXPLICITLY (stamped before any
304	  // charge), so a rate change between now and fulfilment can't re-price it.
305	  const sold: GameOrderPrice = { chargeCents };
306	  let checkout: EmbeddedCheckout | null;
307	  try {
308	    checkout = await createGameOrderPaymentSession(user, cardCents, intent, sold);
309	  } catch (e) {
310	    if (e instanceof GameOrderError) return { error: e.message };
311	    throw e;
312	  }
313	  if (!checkout) {
314	    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
315	  }
316	  return { checkout };
317	}
318	
319	/**

// across every IP-less redemption and wrongly block them. NULLs are distinct.
const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
  quote = await orderQuote(intent, { suppressPromo: true });
}
const promoCampaign = promoCampaignFromCookie(await cookies());

const isAdmin = user.role === "ADMIN";
const freePath = !!intent.free && isAdmin;

// Wallet-aware split. The customer's Review screen computes the exact same split
// (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
// `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
// the balance. Free admin grants skip the split entirely (no money moves).
const useWallet = formData.get("useWallet") !== "0";
// VAT/GST for this customer (Finding 1), resolved from their billing country. The
// rate is constant for the request; the tax cents track whatever net the quote
// settles on after any promo/coupon re-quote below. The wallet split and the card
// leg are computed from the TAX-INCLUSIVE total so the card is charged the same
// total the customer is shown, and the stamped `OrderPrice` carries the tax so the
// confirm route settles it without re-deriving. A free admin grant is never taxed.
const taxCtx = freePath ? { ratePercent: 0, country: "", reverseCharged: false } : await taxContextForUser(user);
const taxOn = (netCents: number) => Math.round((netCents * taxCtx.ratePercent) / 100);
const dueWithTax = (netCents: number) => netCents + taxOn(netCents);
// `let`: a first-month-free hold lost to a concurrent checkout forces a full-price
// re-quote below, which changes the split. Free admin grants skip it entirely.
let { walletApplied, cardCents } = freePath
  ? { walletApplied: 0, cardCents: 0 }
  : walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });

// Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
// provision straight away. placeOrder debits the FULL chargeCents from the wallet
// (or nothing, for a free grant); the balance check inside it holds because a
// $0 card portion means balance >= chargeCents.
if (freePath || cardCents <= 0) {
  let serverId: string;
  try {
    // Reuse the request-scoped IP hash computed above so placeOrder can enforce
    // both the coupon's once-per-person guard and the first-month-free 1/IP cap.
    serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
  } catch (e) {
    if (e instanceof OrderError) return { error: e.message };
    throw e;
  }
  // A wallet-only order is still a real payment (money left the balance) — stamp
  // the same `?purchase=1` marker the card/Stripe path gets via reportPurchase, so
  // ProvisioningOverlay's "just paid" signal covers this path too. Skip it for a
  // free admin grant (freePath): no money moved, nothing to celebrate.
  redirect(`/dashboard/servers/${serverId}${freePath ? "" : "?purchase=1"}`);
}

// RESERVE the first-month-free credit BEFORE opening the Checkout session. This is
// the money-race fix: the card leg settles the discounted price up front, so unless
// this account/IP's one credit is held EXCLUSIVELY here, two concurrent card
// checkouts could each pass eligibility and each collect a free month from one
// eligibility. The reserve's INSERT contends on the same two unique constraints as
// the grant, so exactly one checkout holds it; a loser re-quotes at FULL price so
// its stamped total, card leg and settlement all agree (displayed === charged). The
// hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`, and
// swept as a backstop — an abandoned checkout never permanently burns the offer.
//
// `promoCreditCents > 0` is the honest "this quote carries the free month" signal
// (0 whenever the promo is off, already-redeemed via the re-quote above, or the
// product is out of scope — firstMonthFreeAppliesTo). It is 0 for VPS today, so
// this block is inert for VPS and correct the moment the owner extends the promo to
// any card-checkout product.
let promoReservationToken: string | null = null;
if (quote.promoCreditCents > 0) {
  const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
  const res = await reserveFirstMonthFree({
    userId: user.id,
    ipHash: promoIpHash,
    serviceType: "VPS",
    campaign: promoCampaign,
    chargedCents: quote.chargeCents,
    reservedUntil,
  });
  if (res.reserved) {
    promoReservationToken = res.token;
  } else {
